package com.financialfraudassistant.model;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="budgets", uniqueConstraints=@UniqueConstraint(columnNames={"user_id","category"}), indexes=@Index(name="idx_budget_user", columnList="user_id"))
public class Budget { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Integer id; @Version @Column(columnDefinition = "bigint default 0") private Long version; @ManyToOne(optional=false) @JoinColumn(name="user_id") private User user; @Column(nullable=false) private String category; @Column(name="monthly_limit",nullable=false,precision=12,scale=2) private BigDecimal monthlyLimit; protected Budget(){} public Budget(User u,String c,BigDecimal l){user=u;category=c;monthlyLimit=l;} public Integer getId(){return id;} public String getCategory(){return category;} public BigDecimal getMonthlyLimit(){return monthlyLimit;} public void update(String c,BigDecimal l){category=c;monthlyLimit=l;} }
